#include <bits/stdc++.h>
using namespace std;

#define ll long long

long long bin_search(int f, int b, vector<long long> &a, vector<long long> & pref){
    int m = b - f + 1;
    m /= 3;
    int l = 0;
    int h = m;
    while(h > l){
        int mid = (l + h) / 2;
        ll x = a[f + 2 * mid];
        ll y = a[f + 2 * mid + 1];
        ll z = a[b - mid];
        if (4 * x + 4 * y > 3 *(x + y + z)){
            l = mid + 1;
            
        }
        else{
            h = mid;
        }
    }
    ll ans = 0;
    if (l == 0){
        ans = pref[b + 1] - pref[f];
        ans *= 3;
        
    }
    else if (l == m){
        ans = pref[f + 2 * m ] - pref[f];
        ans *= 4;
    }
    else{
        
        ans = pref[f+2*l] - pref[f];
        ans*=4;
        int count=m -l;
        ans += 3 *(pref[f + 2* l + 3 * count]-pref[f + 2 *l]);
    }
    return ans;
    
    
    
    
    
}

void solve(){
    int n;
    cin >> n;
    n *= 3;
    vector<long long> a(n);
    for(int i = 0 ; i < n ;i++) cin >> a[i];
    
    sort(a.begin(), a.end(), greater<long long>());
    vector<long long> pref(n + 1,0);
    pref[0] = 0;
    for(int i = 0 ; i < n ; i++) pref[i + 1] = pref[i] + a[i];
    
    long long ans = 0;
    long long pref_6x = 0;
    int f = 0, b = n-1;
    for (int i = 0; i < n/3; i++){
        
        long long best_res = bin_search(f, b,a, pref);
        long long curr_ans = pref_6x + best_res;
        ans = max(ans, curr_ans);
        pref_6x += 6 * a[f];
        f++;
        b-=2;
    }
    
    ans = max(ans, pref_6x);
    
    cout << ans << endl;
    
}

int main() {
	int t;
	cin >> t;
	while(t--) solve();

}
